static const char *debugstr_addr( const BYTE *addr )
{
    if (!addr)
        return wine_dbg_sprintf( "(null)" );

    return wine_dbg_sprintf( "%02x:%02x:%02x:%02x:%02x:%02x", addr[0], addr[1], addr[2], addr[3], addr[4], addr[5] );
}
